{"implementation":"def solve(case):
    from fractions import Fraction
    import math

    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "segments" not in case or "budget" not in case:
        raise ValueError("case must contain segments and budget")

    segments = case["segments"]
    budget = case["budget"]
    if not isinstance(segments, list):
        raise ValueError("segments must be an array")
    if isinstance(budget, bool) or not isinstance(budget, int):
        raise ValueError("budget must be an integer")
    if budget < 0:
        raise ValueError("budget must be nonnegative")

    validated = []
    names = set()
    required = ("name", "importance", "minimum", "capacity")
    for segment in segments:
        if not isinstance(segment, dict):
            raise ValueError("each segment must be an object")
        if any(field not in segment for field in required):
            raise ValueError("segment is missing a required field")

        name = segment["name"]
        importance = segment["importance"]
        minimum = segment["minimum"]
        capacity = segment["capacity"]

        if not isinstance(name, str):
            raise ValueError("segment name must be a string")
        if name in names:
            raise ValueError("segment names must be unique")
        names.add(name)

        if isinstance(importance, bool) or not isinstance(importance, (int, float)):
            raise ValueError("importance must be numeric")
        if isinstance(importance, float) and not math.isfinite(importance):
            raise ValueError("importance must be finite")
        if importance < 0:
            raise ValueError("importance must be nonnegative")

        if isinstance(minimum, bool) or not isinstance(minimum, int):
            raise ValueError("minimum must be an integer")
        if isinstance(capacity, bool) or not isinstance(capacity, int):
            raise ValueError("capacity must be an integer")
        if minimum < 0 or capacity < 0 or minimum > capacity:
            raise ValueError("segment quota bounds are invalid")

        validated.append((name, Fraction(importance), minimum, capacity))

    minimum_total = sum(segment[2] for segment in validated)
    capacity_total = sum(segment[3] for segment in validated)
    if budget < minimum_total or budget > capacity_total:
        raise ValueError("budget is infeasible")

    allocations = [segment[2] for segment in validated]
    remaining = budget - minimum_total
    while remaining:
        best_index = None
        best_priority = None
        for index, (_, importance, _, capacity) in enumerate(validated):
            if allocations[index] >= capacity:
                continue
            priority = importance / (allocations[index] + 1)
            if best_index is None or priority > best_priority:
                best_index = index
                best_priority = priority
        allocations[best_index] += 1
        remaining -= 1

    by_name = {
        validated[index][0]: allocation
        for index, allocation in enumerate(allocations)
    }
    return {
        "allocations": allocations,
        "by_name": by_name,
        "total": sum(allocations),
    }
